<?php require_once __DIR__.'/../config.php'; require_role('admin'); $counts=[];foreach(['users','teachers','students','parents','classes','grades'] as $t){$counts[$t]=$conn->query("SELECT COUNT(*) c FROM $t")->fetch_assoc()['c'];} include '../includes/layout-start.php';?><h1>Admin dashboard</h1><div class="grid"><?php foreach($counts as $k=>$v):?><div class="card"><div><?=e(ucfirst($k))?></div><div class="stat"><?=$v?></div></div><?php endforeach;?></div><?php include '../includes/layout-end.php';?>